/**
 * CPU, memory and pods in plain units.
 */
export type Resources = {
  /**
   * CPU in millicores (1000 is one core).
   * @minimum 0
   */
  cpuMillicores: number
  /**
   * Memory in bytes.
   * @minimum 0
   */
  memoryBytes: number
  /**
   * Pods; only where a count of pods applies.
   * @minimum 0
   * @nullable
   */
  pods?: number | null
}

/**
 * How many pods set no limit, for each resource.
 */
export type Unlimited = {
  /**
   * Pods without a CPU limit.
   * @minimum 0
   */
  cpu: number
  /**
   * Pods without a memory limit.
   * @minimum 0
   */
  memory: number
}

/**
 * One namespace's pods together.
 */
export type NamespaceUsage = {
  /**
   * A project: the Namespace has the label `zeabur.com/project`. Absent when namespaces
   * cannot be listed.
   * @nullable
   */
  adopted?: boolean | null
  /**
   * A project's display name, when it has one.
   * @nullable
   */
  displayName?: string | null
  /** What those pods may use at most; a pod without a limit adds nothing. */
  limits: Resources
  /** The namespace. */
  namespace: string
  /** Its Namespace. */
  origin: Origin
  /**
   * Its unfinished pods that were read.
   * @minimum 0
   */
  pods: number
  /** What those pods reserve. */
  requests: Resources
  /** A namespace Kubernetes keeps for itself (`kube-` prefix). */
  system: boolean
  /** Pods that set no limit. */
  unlimited: Unlimited
  usage?: Resources | null
}

/**
 * Whether usage could be read. An open set.
 */
export type MetricsState = (typeof MetricsState)[keyof typeof MetricsState]

export const MetricsState = {
  available: "available",
  "not-installed": "not-installed",
  unreadable: "unreadable",
  unavailable: "unavailable",
} as const

/**
 * How much of the pods were read for the requests. An open set.
 */
export type PodScan = (typeof PodScan)[keyof typeof PodScan]

export const PodScan = {
  complete: "complete",
  partial: "partial",
  unreadable: "unreadable",
} as const

/**
 * Every namespace together.
 */
export type UsageTotals = {
  /** Limits. */
  limits: Resources
  /** Reserved. */
  requests: Resources
  usage?: Resources | null
}

/**
 * What each namespace reserves and uses.
 */
export type ClusterUsage = {
  /** `cluster/usage`. */
  id: string
  /** Each namespace with a pod or a sample, by name. */
  items: NamespaceUsage[]
  /** Whether usage could be read. */
  metrics: MetricsState
  /** `complete`, or `partial` when the read stopped at 5,000 pods. */
  podScan: PodScan
  /**
   * How many unfinished pods were read.
   * @minimum 0
   */
  podsScanned: number
  /**
   * When the newest sample was taken (RFC 3339).
   * @nullable
   */
  timestamp?: string | null
  /** Every namespace together. */
  totals: UsageTotals
  /** What could not be read. */
  unreadable: UnreadableView[]
  /**
   * The window CPU is averaged over, as metrics-server writes it (`15s`).
   * @nullable
   */
  window?: string | null
}

