export const getOpenPodTerminalUrl = (
  project: string,
  pod: string,
  params?: OpenPodTerminalParams,
) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["command"]

    if (Array.isArray(value) && explodeParameters.includes(key)) {
      value.forEach((v) => {
        normalizedParams.append(key, v === null ? "null" : String(v))
      })
      return
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `/api/v1/projects/${encodeURIComponent(String(project))}/pods/${encodeURIComponent(String(pod))}/exec?${stringifiedParams}`
    : `/api/v1/projects/${encodeURIComponent(String(project))}/pods/${encodeURIComponent(String(pod))}/exec`
}

/**
 * Binary messages carry terminal bytes both ways; text messages are JSON control frames,
 * `ClientFrame` to the server and `ServerFrame` to the browser. The handshake answers `101
 * Switching Protocols`; every later failure (`403` with `denied` naming `create` on
 * `pods/exec`; a pod or container that does not exist, a container that is not running) arrives
 * as an `error` frame, which a browser can read where it cannot read a refused handshake. After
 * `exit` or `error` the server closes with `1000`; it closes with `4001` after 15 minutes without
 * a byte either way. A handshake
 * from another origin is refused with `403`.
 * @summary A terminal in a container, over a WebSocket.
 */
export const openPodTerminal = async (
  project: string,
  pod: string,
  params?: OpenPodTerminalParams,
  options?: Parameters<typeof zeaburFetch>[1],
): Promise<unknown> => {
  return zeaburFetch<unknown>(getOpenPodTerminalUrl(project, pod, params), {
    ...options,
    method: "GET",
  })
}

