export const getSetClusterNameUrl = () => {
  return `/api/v1/settings/cluster-name`
}

/**
 * @summary Renames the cluster in Zeabur, or goes back to the name Zeabur finds with `null`, by writing
the settings ConfigMap as you (created the first time). Who may: whoever may update (and
create) the ConfigMap `zeabur-settings` in Zeabur's namespace. Changes nothing in the cluster
itself.
 */
export const setClusterName = async (
  clusterNameChange: ClusterNameChange,
  options?: Parameters<typeof zeaburFetch>[1],
): Promise<ClusterNameSetting> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {}
    if (h instanceof Headers) return Object.fromEntries(h.entries())
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      )
    }
    const headers: Record<string, string | readonly string[]> = {}
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value
    }
    return headers
  }
  return zeaburFetch<ClusterNameSetting>(getSetClusterNameUrl(), {
    ...options,
    method: "PUT",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(clusterNameChange),
  })
}

